CREATE OR REPLACE FUNCTION public.buka_penggajian(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare g penggajian;
begin
  if not kelola_gaji() then raise exception 'Hanya Owner/HRD'; end if;
  select * into g from penggajian where id = p_id for update;
  if g.biaya_id is not null then update biaya_outlet set deleted_at = now() where id = g.biaya_id; end if;
  update penggajian set status = 'draft', final_at = null where id = p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.finalkan_penggajian(p_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare g penggajian; v_total bigint; v_kat uuid; v_biaya uuid;
begin
  if not kelola_gaji() then raise exception 'Hanya Owner/HRD yang bisa memfinalkan gaji'; end if;
  select * into g from penggajian where id = p_id for update;
  if g.id is null then raise exception 'Penggajian tidak ditemukan'; end if;
  select coalesce(sum(total), 0) into v_total from slip_gaji where penggajian_id = p_id;
  if v_total <= 0 then raise exception 'Belum ada slip bernilai'; end if;
  select id into v_kat from kategori_biaya where nama ilike 'biaya gaji' limit 1;
  if g.biaya_id is not null then
    update biaya_outlet set jumlah = v_total, deleted_at = null where id = g.biaya_id returning id into v_biaya;
  end if;
  if v_biaya is null then
    insert into biaya_outlet (mode, outlet_id, tanggal, kategori_id, jumlah, keterangan, sumber)
    values (g.mode, g.outlet_id, (g.periode + interval '1 month - 1 day')::date, v_kat, v_total,
            'Gaji karyawan ' || to_char(g.periode, 'MM/YYYY') || ' (penggajian)', 'pusat')
    returning id into v_biaya;
  end if;
  update penggajian set status = 'final', final_at = now(), biaya_id = v_biaya where id = p_id;
  return v_total;
end $function$;

CREATE OR REPLACE FUNCTION public.simpan_opname(p_outlet uuid, p_tanggal date, p_items jsonb, p_catatan text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare oid uuid; x jsonb; b bahan; sist numeric; fis numeric; hu numeric; tot numeric := 0;
begin
  if not (gudang_pusat() or peran_di_outlet(p_outlet, '{spv}')) then raise exception 'Hanya SPV outlet atau Gudang Pusat'; end if;
  insert into opname (outlet_id, tanggal, catatan) values (p_outlet, coalesce(p_tanggal, current_date), left(p_catatan, 300)) returning id into oid;
  for x in select * from jsonb_array_elements(coalesce(p_items, '[]')) loop
    select * into b from bahan where id = (x->>'bahan_id')::uuid;
    if b.id is null then continue; end if;
    fis := greatest(coalesce((x->>'qty_fisik')::numeric, 0), 0);
    select coalesce(jumlah, 0) into sist from stok where mode = 'asli' and outlet_id = p_outlet and bahan_id = b.id;
    sist := coalesce(sist, 0);
    hu := coalesce(nullif(b.harga_jual_gudang, 0), b.harga_beli, 0) / nullif(b.konversi, 0);
    insert into item_opname (opname_id, bahan_id, qty_sistem, qty_fisik, harga_unit, nilai) values (oid, b.id, sist, fis, coalesce(hu, 0), round(fis * coalesce(hu, 0)));
    if fis <> sist then perform geser_stok('asli', p_outlet, b.id, fis - sist, 'opname', oid, 'Opname ' || coalesce(p_tanggal, current_date)); end if;
    tot := tot + round(fis * coalesce(hu, 0));
  end loop;
  update opname set total_nilai = tot where id = oid;
  return oid;
end $function$;


create policy kelola on penggajian for all using(true) with check(true);